export function total(order: Order): Money {
  if (!isValid(order)) return Money.Zero;
  return applyDiscount(subtotal(order), order.discount);
}

function isValid(order: Order): boolean { return order.lines.length > 0; }
function subtotal(order: Order): Money {
  return order.lines.reduce((sum, line) => sum + line.amount, Money.Zero);
}
function applyDiscount(total: Money, discount: Discount): Money { return total.minus(discount); }
